#include "vulkan_shader.h"
namespace localimage::vulkan {VulkanShader::~VulkanShader(){destroy();}bool VulkanShader::create(VkDevice d,const uint32_t*c,size_t n,std::string&e){destroy();if(!c||!n){e="empty SPIR-V";return false;}VkShaderModuleCreateInfo ci{VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO};ci.codeSize=n*sizeof(uint32_t);ci.pCode=c;VkResult r=vkCreateShaderModule(d,&ci,nullptr,&m_);if(r!=VK_SUCCESS){e="vkCreateShaderModule: "+std::to_string((int)r);return false;}d_=d;return true;}void VulkanShader::destroy(){if(d_&&m_)vkDestroyShaderModule(d_,m_,nullptr);d_=VK_NULL_HANDLE;m_=VK_NULL_HANDLE;}}
